import io from "socket.io-client";

let socket = null;

// Initialize WebSocket connection after successful login
export const initSocket = (apiUrl = "http://localhost:4000") => {
  if (!socket) {
    socket = io(apiUrl, {
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      reconnectionAttempts: 5,
      transports: ["websocket", "polling"],
    });

    socket.on("connect", () => {
      console.log("✓ WebSocket connected:", socket.id);
    });

    socket.on("disconnect", () => {
      console.log("✗ WebSocket disconnected");
    });

    socket.on("connect_error", (error) => {
      console.error("WebSocket error:", error);
    });
  }

  return socket;
};

// Get existing socket instance
export const getSocket = () => socket;

// Disconnect socket
export const disconnectSocket = () => {
  if (socket) {
    socket.disconnect();
    socket = null;
  }
};

// Listen for poles data (initial load)
export const onPolesData = (callback) => {
  if (!socket) return;
  socket.on("poles-data", callback);
};

// Listen for pole updates (real-time)
export const onPoleUpdate = (callback) => {
  if (!socket) return;
  socket.on("pole-update", callback);
};

// Fetch a specific pole on-demand
export const getPole = (poleId, callback) => {
  if (!socket) return;
  socket.emit("get-pole", poleId, callback);
};

// Remove listeners
export const removeListener = (event) => {
  if (!socket) return;
  socket.off(event);
};

export default socket;
